const day0=tx=>tx.f&&tx.f.day0_on&&tx.f.day0?tx.f.day0:(tx.f&&tx.f.acceptance)||'';
const cDeadRaw=(tx,c)=>{if(!c||c.days===''||c.days==null)return c&&c.k==='coe'&&c.date?c.date:'';let n=parseInt(c.days,10);if(isNaN(n))return '';let base;if(c.from==='coe'&&c.k!=='coe'){n=Math.abs(n);const ce=(tx.cont||[]).find(x=>x.k==='coe');base=pd(ce?cdate(tx,ce):'');if(!base)return '';return iso(c.biz?addBD(base,-n):addD(base,-n))}base=pd(day0(tx));if(!base)return '';return iso(c.biz?addBD(base,n):addD(base,n))};
