function baseDate(tx,code){if(code==='ACC')return day0(tx);if(LSBASE[code])return tx.f[LSBASE[code]]||'';const c=(tx.cont||[]).find(x=>x.k&&x.k.toUpperCase()===code);return c?cdate(tx,c):''}
function linkCont(tx,i){if(!i.ms||!i.drv||(parseInt(i.days,10)||0)!==0)return;const c=(tx.cont||[]).find(x=>x.k&&x.k.toUpperCase()===i.drv);if(c)c.removed=!!i.done}
