 if(i.drv.startsWith('T:')){const t=tx.checklist.find(x=>x.id===i.drv.slice(2));base=t?(t.done?(t.doneAt||''):(dep<8?itemDue(tx,t,dep+1):'')):''}else base=baseDate(tx,i.drv);
 const d=pd(base);const n=parseInt(i.days||0,10)||0;if(!d)return '';const r=i.biz?addBD(d,n):addD(d,n);
