 text=text.replace(/\s+/g,' ').replace(/^[\s,:;-]+/,'').replace(/^please\s+/i,'').replace(/[.!\s]+$/,'').trim();text=text.charAt(0).toUpperCase()+text.slice(1);if(who)text=who+' - '+text;
 const md=aiModal(`<h3 style="margin:0">Add as a task</h3><div class="mut small" style="margin:2px 0 12px">${esc(txLabel(t))} · from ${esc(m0.by||'chat')}</div><label class="f">Task<input id="ctText" value="${esc(text)}"></label><div class="row" style="gap:10px"><label class="f" style="flex:1">Assign to<select id="ctWho">${whoOpts(who)}</select></label><label class="f" style="flex:1">Due<input type="date" id="ctDue" value="${today()}"></label></div><div class="row end" style="margin-top:10px"><button class="btn" data-m="no">Cancel</button><button class="btn pri" id="ctOk">Add task</button></div>`);
