 if(l){l.innerHTML=chatMsgs(tx);chatScroll();const nw=chatFor(tx.id).filter(m=>m.at>seenAt(tx.id)&&m.by!==me());if(nw.length)toast(nw[nw.length-1].by+': '+nw[nw.length-1].text.slice(0,60));markSeen(tx.id)}
 else{const nw=chatFor(tx.id).filter(m=>m.at>(S._chatToast||0)&&m.at>seenAt(tx.id)&&m.by!==me());if(nw.length){S._chatToast=Date.now();toast('💬 '+nw[nw.length-1].by+' posted in this property’s chat (Summary tab)')}}
