function fillParty(tx,p,c){const P=PARTY[p];['company','phone','email','dre'].forEach(k=>{if(P[k]&&c[k]){tx.f[P[k]]=c[k];const el=app.querySelector(`[data-f="${P[k]}"]`);if(el)el.value=c[k]}});tx.f[p+'_cid']=c.id;touch(tx)}
function findContact(role,name,vals){const n=String(name||'').trim().toLowerCase();if(!n)return null;const cl=CLIENT_ROLES.includes(role);const okR=x=>x.role===role||(cl&&CLIENT_ROLES.includes(x.role));const ph=v=>String(v||'').replace(/\D/g,'').slice(-10);
 let c=S.contacts.find(x=>x.name&&x.name.trim().toLowerCase()===n&&okR(x));if(c||!vals)return c||null;
 const lw=v=>String(v||'').trim().toLowerCase().split(/\s+/).pop();const okN=x=>lw(x.name)===lw(n);if(vals.dre)c=S.contacts.find(x=>okR(x)&&okN(x)&&x.dre&&String(x.dre).replace(/\D/g,'')===String(vals.dre).replace(/\D/g,''));if(!c&&vals.email)c=S.contacts.find(x=>okR(x)&&okN(x)&&x.email&&x.email.toLowerCase()===vals.email.toLowerCase());return c||null}
function syncContact(tx,p){const P=PARTY[p];const name=String(tx.f[P.name]||'').trim();if(name.length<2)return;
 const vals={};['company','phone','email','dre'].forEach(k=>{if(P[k])vals[k]=String(tx.f[P[k]]||'').trim()});
 let c=S.contacts.find(x=>x.id===tx.f[p+'_cid']);if(c&&c.name.trim().toLowerCase()!==name.toLowerCase())c=null;if(!c)c=findContact(P.role,name,vals);
 if(c){let fl=false;['company','phone','email','dre'].forEach(k=>{if(P[k]&&!String(tx.f[P[k]]||'').trim()&&c[k]){tx.f[P[k]]=c[k];vals[k]=c[k];fl=true}});if(fl)touch(tx)}
 if(c){const nc=clone(c);let ch=false;for(const k in vals){if(vals[k]&&vals[k]!==(nc[k]||'')){nc[k]=vals[k];ch=true}}if(ch)save('contacts',nc).catch(dbErr);if(tx.f[p+'_cid']!==c.id){tx.f[p+'_cid']=c.id;touch(tx)}}
 else{const nc=Object.assign({id:uid(),name,role:P.role,createdAt:Date.now()},vals);save('contacts',nc).catch(dbErr);tx.f[p+'_cid']=nc.id;touch(tx);toast('Saved '+name+' to '+(CLIENT_ROLES.includes(P.role)?'Buyers & Sellers':'Associates'))}}
