 const ms=tx.checklist.filter(i=>i.ms&&!isContTask(tx,i)).map(i=>({label:i.text,days:i.drv&&i.drv!=='DATE'?String(i.days||0):'',d:i.done?(i.doneAt||itemDue(tx,i)):itemDue(tx,i),done:i.done}));
