 const dates=drows.length?`<div class="dg">${drows.map(x=>`<div class="dgr ${x.done?'waived':''}"><span>${esc(x.label)}</span><span class="c">${esc(x.days||'')}</span><span class="r">${x.wv?esc(x.wv===true?'Waived':x.wv):esc(fmtX(x.d))}</span></div>`).join('')}</div>`:'';
 const reps=String(f.repairs||'').split('\n').map(s=>s.replace(/^[-•*\s]+/,'').trim()).filter(Boolean);const kn=tx.notes.filter(n=>n.pub&&n.key);
