 let done=0,fail=0;for(const [col,id,data] of jobs){let ok=false;for(let a=0;a<5&&!ok;a++){try{await db.collection(col).doc(id).set(data);ok=true}catch(e){await new Promise(r=>setTimeout(r,1500*(a+1)))}}if(!ok)fail++;done++;$('#clBar').style.width=(done/jobs.length*100)+'%';$('#clStat').textContent=`${done} of ${jobs.length} saved`;await new Promise(r=>setTimeout(r,150))}
