 function show(c){const q=c.q,qs=q.replace(/_/g,' ');let L=fcat().filter(x=>!q||x.k.includes(q)||x.l.toLowerCase().includes(qs));L.sort((a,b)=>(b.k.startsWith(q)?1:0)-(a.k.startsWith(q)?1:0));L=L.slice(0,50);if(!L.length){hide();return}
  const tx=getTx();const m=tx?mergeMap(tx):{};st={c,L,i:0};
  box.innerHTML=L.map((x,i)=>`<div class="aci ${i===0?'on':''}" data-i="${i}"><code>{{${esc(x.k)}}}</code><span class="acl">${esc(x.l)}</span><span class="mut">${esc(x.g)}${tx&&!SUMF[x.k]&&m[x.k]?' · '+esc(String(m[x.k]).slice(0,40)):''}</span></div>`).join('');
  box.classList.remove('hidden');box.style.left=Math.max(8,Math.min(c.x,innerWidth-470))+'px';box.style.top=Math.max(8,Math.min(c.y+4,innerHeight-290))+'px'}
