  if(c.t.isContentEditable){c.t.focus();const r=document.createRange();r.setStart(c.n,c.s);let e2=c.e;if(!c.cond&&(c.n.nodeValue||'').slice(e2,e2+2)==='}}')e2+=2;r.setEnd(c.n,e2);const sl=getSelection();sl.removeAllRanges();sl.addRange(r);document.execCommand('insertText',false,tok)}
