function pAgents(){const M=new Map();S.tx.forEach(t=>pPeople(t).forEach(p=>{if((p.group!=='rep'&&p.group!=='oth')||p.team)return;const a=M.get(p.email)||{email:p.email,name:p.name,files:[]};if(!a.name&&p.name)a.name=p.name;a.files.push({tx:t,p});M.set(p.email,a)}));return [...M.values()].sort((a,b)=>String(a.name||a.email).localeCompare(String(b.name||b.email)))}
