 const rowFn=t=>{const P=t.portal||{};const L=pPeople(t);return `<div class="prow"><div class="row between" style="gap:10px"><div><b>${esc(t.f.address||'(no address)')}</b> <span class="mut small">${esc(KLABEL[kindOf(t)][0])}</span></div><div class="row" style="gap:6px"><label class="row small" style="gap:4px"><input type="checkbox" data-poff="${t.id}" ${P.off?'':'checked'}> Share this file</label>${L.some(p=>p.on&&!(P.inv||{})[p.email])?`<button class="btn sm" data-act="p-invall" data-id="${t.id}" title="Email an invite to everyone who can sign in and hasn't been invited">✉ Invite all</button>`:''}<button class="btn sm" data-act="p-add" data-id="${t.id}">+ Add person</button></div></div>
  <div class="pchips">${L.length?L.map(p=>{const sn=seen[p.email];const dup=L.filter(y=>y.name&&y.name===p.name).length>1;return `<span class="pchip ${p.on?'on':p.team?'tm':'off'}" title="${esc(p.email)} · ${esc(p.role)}${sn?' · last viewed '+fmtWhen2(sn):''}"><b>${esc(p.name||p.email)}</b>${dup?`<span class="small">${esc(p.email)}</span>`:''}<select class="pgsel" data-pg="${t.id}|${esc(p.email)}" title="Group on this file (decides what they see)">${Object.keys(PG).map(g=>`<option value="${g}" ${g===p.group?'selected':''}>${esc(PG[g])}</option>`).join('')}</select><span class="mut small">${p.team?' · team member':p.on?(sn?' · viewed '+fmtWhen2(sn):' · can sign in'):p.blocked?' · blocked':!c.on||P.off?' · off':' · not shared'}</span>${p.on&&!p.team?(P.inv&&P.inv[p.email]?`<span class="mut small" title="Invite sent">✉ ${fmtWhen2(P.inv[p.email])}</span>`:`<button class="ib" data-act="p-inv" data-id="${t.id}" data-e="${esc(p.email)}" title="Email them an invite from the team address">✉</button>`):''}${p.team?'':`<button class="ib" data-act="p-prev" data-id="${t.id}" data-e="${esc(p.email)}" title="See what they see">👁</button>${p.src==='added'?`<button class="ib" data-act="p-rm" data-id="${t.id}" data-e="${esc(p.email)}" title="Remove">✕</button>`:`<button class="ib" data-act="p-block" data-id="${t.id}" data-e="${esc(p.email)}" title="${p.blocked?'Allow again':'Block this person'}">${p.blocked?'↺':'⊘'}</button>`}`}</span>`}).join(''):'<span class="mut small">No emails on this file yet. Add emails in Participants, or add a person here.</span>'}</div></div>`};const rows=deals.slice(0,200).map(rowFn).join('');
