const ptNavBadge=(cls)=>{if(!S.pchat||!S.pchat.length)return '';const ids=[...new Set(S.pchat.map(m=>m.txId))];const n=ids.reduce((a,id)=>a+ptUnread(id),0);return n?` <span class="nbadge ${cls||''}" title="Unread messages from clients and agents">${n>99?'99+':n}</span>`:''};
