  let ids=[],pt='',pages=0;do{const r=await M.gget('messages?maxResults=100&q='+encodeURIComponent('after:'+Math.floor(since/1000))+(pt?'&pageToken='+pt:''));(r.messages||[]).forEach(m=>ids.push(m.id));pt=r.nextPageToken||'';pages++}while(pt&&pages<8);
